<script setup>
import { computed, ref } from 'vue'; import { router, useForm } from '@inertiajs/vue3';
const props=defineProps({trials:Array}); const editing=ref(null); const search=ref(''); const courseFilter=ref('all'); const statusFilter=ref('all'); const courses=computed(()=>[...new Map(props.trials.map(t=>[t.course?.id,t.course]).filter(([id])=>id)).values()]); const filtered=computed(()=>props.trials.filter(t=>{const q=search.value.trim().toLocaleLowerCase('fr');if(q&&!`${t.first_name} ${t.last_name} ${t.email} ${t.phone}`.toLocaleLowerCase('fr').includes(q))return false;if(courseFilter.value!=='all'&&String(t.course?.id)!==String(courseFilter.value))return false;return statusFilter.value==='all'||t.status===statusFilter.value})); const form=useForm({first_name:'',last_name:'',email:'',phone:'',preferred_date:'',dance_role:'',message:'',status:'pending'}); const date=v=>new Date(`${String(v).slice(0,10)}T12:00:00`).toLocaleDateString('fr-CH'); const money=v=>Number(v||0).toLocaleString('fr-CH',{minimumFractionDigits:2});
function edit(t){editing.value=t;form.defaults({first_name:t.first_name,last_name:t.last_name,email:t.email,phone:t.phone,preferred_date:String(t.preferred_date).slice(0,10),dance_role:t.dance_role||'',message:t.message||'',status:t.status});form.reset();form.clearErrors()} function close(){editing.value=null;form.reset()} function submit(){form.put(`/admin/cours-essai/${editing.value.id}`,{preserveScroll:true,onSuccess:close})} const remove=t=>confirm(`Supprimer la demande d’essai de ${t.first_name} ${t.last_name} ?`)&&router.delete(`/admin/cours-essai/${t.id}`,{preserveScroll:true});
</script>
<template><section class="overflow-hidden rounded-3xl bg-white"><div class="px-6 pt-5"><h2 class="font-serif text-2xl">Demandes de cours d’essai</h2><p class="mt-1 text-xs text-black/40">{{filtered.length}} demande{{filtered.length>1?'s':''}} affichée{{filtered.length>1?'s':''}}</p></div><div class="grid gap-3 px-6 py-5 md:grid-cols-[1.5fr_1fr_1fr]"><input v-model="search" type="search" placeholder="Rechercher un élève…" class="rounded-xl border border-black/10 bg-[#faf9f6] px-4 py-3 text-sm"/><select v-model="courseFilter" class="rounded-xl border border-black/10 bg-white px-4 py-3 text-sm"><option value="all">Tous les cours</option><option v-for="course in courses" :key="course.id" :value="course.id">{{course.title}}</option></select><select v-model="statusFilter" class="rounded-xl border border-black/10 bg-white px-4 py-3 text-sm"><option value="all">Tous les statuts</option><option value="pending">À traiter</option><option value="confirmed">Confirmée</option><option value="completed">Terminée</option><option value="cancelled">Annulée</option></select></div><div v-if="filtered.length" class="overflow-x-auto"><table class="w-full min-w-[1000px] text-left"><thead class="bg-[#f7f5f0] text-xs text-black/45"><tr><th class="p-4">Élève</th><th class="p-4">Cours</th><th class="p-4">Date</th><th class="p-4">Tarif</th><th class="p-4 text-right">Actions</th></tr></thead><tbody><tr v-for="trial in filtered" :key="trial.id"><td class="p-5"><strong>{{trial.first_name}} {{trial.last_name}}</strong><p class="text-xs text-black/40">{{trial.email}}</p></td><td class="p-5">{{trial.course?.title}}</td><td class="p-5">{{date(trial.preferred_date)}}</td><td class="p-5">{{trial.trial_is_free?'Gratuit':`${money(trial.trial_price)} CHF${trial.trial_payment_on_site?' · sur place':''}`}}</td><td class="p-5"><div class="flex justify-end gap-2"><a :href="`mailto:${trial.email}`" class="rounded-full border px-3 py-2 text-xs">Contacter</a><button @click="edit(trial)" class="grid h-9 w-9 place-items-center rounded-full bg-black/5" title="Modifier">✎</button><button @click="remove(trial)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500" title="Supprimer">×</button></div></td></tr></tbody></table></div><p v-else class="p-16 text-center text-black/40">Aucune demande ne correspond aux filtres.</p></section><div v-if="editing" class="fixed inset-0 z-50 grid place-items-center bg-black/45 p-4" @click.self="close"><form @submit.prevent="submit" class="w-full max-w-xl rounded-3xl bg-white p-7"><div class="flex justify-between"><h2 class="font-serif text-3xl">Modifier la demande</h2><button type="button" @click="close" class="grid h-9 w-9 place-items-center rounded-full bg-black/5">×</button></div><div class="mt-6 grid gap-3 sm:grid-cols-2"><input v-model="form.first_name" class="rounded-xl border px-4 py-3" placeholder="Prénom"/><input v-model="form.last_name" class="rounded-xl border px-4 py-3" placeholder="Nom"/><input v-model="form.email" type="email" class="rounded-xl border px-4 py-3"/><input v-model="form.phone" class="rounded-xl border px-4 py-3"/><input v-model="form.preferred_date" type="date" class="rounded-xl border px-4 py-3"/><select v-model="form.status" class="rounded-xl border bg-white px-4 py-3"><option value="pending">À traiter</option><option value="confirmed">Confirmée</option><option value="completed">Terminée</option><option value="cancelled">Annulée</option></select><textarea v-model="form.message" class="rounded-xl border p-3 sm:col-span-2" rows="3"></textarea></div><p v-if="Object.keys(form.errors).length" class="mt-3 text-sm text-red-600">{{Object.values(form.errors)[0]}}</p><button class="mt-5 w-full rounded-full bg-ink py-3 font-bold text-white">Enregistrer</button></form></div></template>
